import type { FactSource } from '@/components/exhibition/FactNote';

/*
 * More at each stop, beyond the poster's words: what happened, in two or
 * three plain sentences for a child; where, on a small map of Europe; and a
 * few things to look closer at in the photograph, each a spot on it. None
 * of it is the poster's: every word is new, from the sources given with it
 * (the USHMM Holocaust Encyclopedia first), and is marked for the owner's
 * review. The sources are in the Sources drawer, under the date, never on
 * the screen (sources.ts).
 *
 * The map is the land of Europe only, from Natural Earth (public domain),
 * drawn once into europe.svg on a Mercator projection (longitude -6 to 36,
 * latitude 41 to 59): no borders, since the borders of 1933 to 1945 are not
 * today's, and the place is named beside it.
 */

export type CloserSpot = {
  /** Where the spot sits on the photograph: percent of its width from the left, and of its height from the top. */
  x: number;
  y: number;
  title: string;
  text: string;
  sources: readonly FactSource[];
};

export type StopWhere = {
  /** The place, as named beside the map ("Berlin", "Across Germany and Austria"). */
  label: string;
  /** Where that is today, where the borders have changed ("Kyiv, today the capital of Ukraine"). */
  today?: string;
  lat: number;
  lon: number;
  /** A word on what the light marks, where it is not the whole story ("This photograph is from here…"). */
  note?: string;
  /** Across a whole country, not one place: the map shows a wide, soft light rather than a point. */
  wide?: boolean;
};

export type StopMore = {
  happened: { text: string; sources: readonly FactSource[] };
  where: StopWhere;
  closer: readonly CloserSpot[];
};

/** The map: Natural Earth's land, 1:50m, drawn to 600 × 407. */
export const MAP_SRC = '/exhibitions/holocaust/timeline/europe.svg';
export const MAP_CREDIT: FactSource = { label: 'Natural Earth, land at 1:50m (public domain), via the world-atlas package', href: 'https://www.naturalearthdata.com/' };
const LON_MIN = -6;
const LON_MAX = 36;
const LAT_MAX = 59;
const W = 600;
export const MAP_H = 407;
const RAD = Math.PI / 180;
const K = W / ((LON_MAX - LON_MIN) * RAD);
const merc = (lat: number) => Math.log(Math.tan(Math.PI / 4 + (lat * RAD) / 2));

/** A place on the map, as percent of the map's width and height (the projection europe.svg was drawn with). */
export function mapPoint(lat: number, lon: number): { x: number; y: number } {
  const x = (lon - LON_MIN) * RAD * K;
  const y = (merc(LAT_MAX) - merc(lat)) * K;
  return { x: (x / W) * 100, y: (y / MAP_H) * 100 };
}

